package com.android_dev.rentaly_management.DTO;
import java.math.BigDecimal; import java.time.LocalDate; import java.time.LocalDateTime; import java.util.List; import java.util.UUID;
public class InvoiceRequest { public UUID contract_id; public String invoice_number, note, status; public LocalDateTime issued_at; public LocalDate due_date; public BigDecimal subtotal, discount_amount, tax_amount, total_amount; public List<InvoiceItemRequest> items; public InvoiceRequest(UUID contract, String number, LocalDate due, BigDecimal subtotal, BigDecimal discount, BigDecimal tax, BigDecimal total, String note, String status) { contract_id=contract; invoice_number=number; due_date=due; this.subtotal=subtotal; discount_amount=discount; tax_amount=tax; total_amount=total; this.note=note; this.status=status; } }
